# enem-2025-linguagens-ingles (1–5 = inglês) e enem-2025-linguagens-espanhol (1–5 = espanhol); 6–45 iguais nas duas.
# Poemas e letras de canção só como imagem (Q3 inglês, Q1 e Q3 espanhol, Q16, Q28), para manter os versos.
# Crônica das questões 6 a 10 copiada dos blocos do PDF (pág. 6); as indicações de linha "(l. N)" das alternativas saem, porque o site não numera linhas.
import sys, pathlib, re
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent / "tools"))
import pymupdf
from enem_aj import carregar_enem, enunciado_enem, paragrafos_enem

D = carregar_enem("enem-2025-dia1-azul")
p = lambda *xs: "".join(f"<p>{x}</p>" for x in xs)
PDF = pathlib.Path(__file__).resolve().parent / "fontes" / "enem-2025-dia1-azul-prova.pdf"


def figs(*pares):
    return [{"arquivo": a, "alt": t} for a, t in pares]


def poema(n, alt, arq=None):
    """Poema ou letra como imagem: [[fig:1]], a referência e o comando."""
    par = paragrafos_enem(D[n])
    fonte = [x for t, x in par if t == "fonte"][-1]
    cmd = [x for t, x in par if t == "p"][-1]
    arq = arq or "q" + str(n).replace("-", "").zfill(2 if "-" not in str(n) else 4)
    return {"enunciado": f'[[fig:1]]<p class="fonte">{fonte}</p>' + p(cmd), "imagens": figs((arq, alt))}


def fig_antes(n, arq, alt):
    """Figura sem texto próprio: figura, referência e comando (o PDF às vezes põe a referência depois do comando)."""
    par = paragrafos_enem(D[n])
    fonte = " ".join(x for t, x in par if t == "fonte")
    cmd = [x for t, x in par if t == "p"][-1]
    return {"enunciado": f'[[fig:1]]<p class="fonte">{fonte}</p>' + p(cmd), "imagens": figs((arq, alt))}


SEM_LINHA = lambda s: re.sub(r"\s*\(l\. [\d\-]+\)", "", s)


def Q_(n, materia, assunto, expl, tags=(), trocas=(), extra=None, alts=None):
    q = {"materia": materia, "assunto": assunto, "area": "Linguagens", "tags": list(tags), "numeroOriginal": int(str(n).split("-")[0]),
         "enunciado": enunciado_enem(D[n], trocas), "alternativas": dict(alts or D[n]["alternativas"]), "imagens": [], "explicacao": expl}
    if extra: q.update(extra)
    q["alternativas"] = {k: SEM_LINHA(v) for k, v in q["alternativas"].items()}
    return q


# crônica das questões 6 a 10 (blocos de parágrafo da pág. 6)
def _cronica():
    pg = pymupdf.open(PDF)[5]; pars = []
    for b in pg.get_text("dict")["blocks"]:
        if b["type"] or not (124 <= b["bbox"][0] <= 125): continue
        s = ""
        for l in b["lines"]:
            t = "".join(sp["text"] for sp in l["spans"]).strip()
            if s.endswith("-") and t[:1].islower(): s = s[:-1] + t
            else: s = (s + " " + t).strip()
        pars.append(re.sub(r"\s+", " ", s))
    return pars


